const stories = [
    { nome: "mariana.fotografia", imagem: "https://picsum.photos/id/65/80/80" },
        { nome: "joao.viajante", imagem: "https://picsum.photos/id/91/80/80" },
            { nome: "ana.design", imagem: "https://picsum.photos/id/177/80/80" },
                { nome: "carlos.musica", imagem: "https://picsum.photos/id/22/80/80" },
                    { nome: "julia.arte", imagem: "https://picsum.photos/id/169/80/80" },
                        { nome: "pedro.esportes", imagem: "https://picsum.photos/id/176/80/80" },
                            { nome: "larissa.cozinha", imagem: "https://picsum.photos/id/292/80/80" }
                            ];

                            // Dados das Postagens
                            const postagens = [
                                {
                                        autor: "mariana.fotografia",
                                                perfil: "https://picsum.photos/id/65/40/40",
                                                        imagem: "https://picsum.photos/id/1015/600/600",
                                                                curtidas: 1245,
                                                                        legenda: "Dia perfeito para capturar a natureza! 🌿📸",
                                                                                tempo: "2 horas atrás"
                                                                                    },
                                                                                        {
                                                                                                autor: "joao.viajante",
                                                                                                        perfil: "https://picsum.photos/id/91/40/40",
                                                                                                                imagem: "https://picsum.photos/id/1036/600/600",
                                                                                                                        curtidas: 892,
                                                                                                                                legenda: "Novos lugares, novas histórias ✈️🌍",
                                                                                                                                        tempo: "5 horas atrás"
                                                                                                                                            },
                                                                                                                                                {
                                                                                                                                                        autor: "ana.design",
                                                                                                                                                                perfil: "https://picsum.photos/id/177/40/40",
                                                                                                                                                                        imagem: "https://picsum.photos/id/1019/600/600",
                                                                                                                                                                                curtidas: 2103,
                                                                                                                                                                                        legenda: "Criando algo especial hoje ✨🎨",
                                                                                                                                                                                                tempo: "8 horas atrás"
                                                                                                                                                                                                    }
                                                                                                                                                                                                    ];

                                                                                                                                                                                                    // Carregar Stories
                                                                                                                                                                                                    function carregarStories() {
                                                                                                                                                                                                        const container = document.getElementById('stories');
                                                                                                                                                                                                            
                                                                                                                                                                                                                stories.forEach(story => {
                                                                                                                                                                                                                        const div = document.createElement('div');
                                                                                                                                                                                                                                div.className = 'flex flex-col items-center gap-1 flex-shrink-0 cursor-pointer';
                                                                                                                                                                                                                                        div.innerHTML = `
                                                                                                                                                                                                                                                    <div class="story-border">
                                                                                                                                                                                                                                                                    <img src="${story.imagem}" alt="${story.nome}" 
                                                                                                                                                                                                                                                                                        class="w-16 h-16 rounded-full object-cover border-2 border-white">
                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                <span class="text-xs max-w-16 truncate">${story.nome.split('.')[0]}</span>
                                                                                                                                                                                                                                                                                                                        `;
                                                                                                                                                                                                                                                                                                                                container.appendChild(div);
                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                    // Carregar Postagens
                                                                                                                                                                                                                                                                                                                                    function carregarPostagens() {
                                                                                                                                                                                                                                                                                                                                        const container = document.getElementById('feed');
                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                postagens.forEach(post => {
                                                                                                                                                                                                                                                                                                                                                        const artigo = document.createElement('article');
                                                                                                                                                                                                                                                                                                                                                                artigo.className = 'bg-white border border-gray-200 rounded-lg overflow-hidden';
                                                                                                                                                                                                                                                                                                                                                                        artigo.innerHTML = `
                                                                                                                                                                                                                                                                                                                                                                                    <!-- Cabeçalho da Postagem -->
                                                                                                                                                                                                                                                                                                                                                                                                <div class="flex items-center justify-between p-3">
                                                                                                                                                                                                                                                                                                                                                                                                                <div class="flex items-center gap-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                    <img src="${post.perfil}" alt="${post.autor}" 
                                                                                                                                                                                                                                                                                                                                                                                                                                                            class="w-8 h-8 rounded-full object-cover">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <span class="font-semibold text-sm">${post.autor}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <i class="fa-solid fa-ellipsis cursor-pointer text-gray-600"></i>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <!-- Imagem da Postagem -->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <img src="${post.imagem}" alt="Postagem" class="w-full aspect-square object-cover">

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <!-- Botões de Ação -->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div class="p-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div class="flex justify-between items-center mb-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div class="flex gap-4 text-2xl">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button class="btn-curtir cursor-pointer hover:opacity-60" onclick="curtir(this)">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <i class="fa-regular fa-heart"></i>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <button class="cursor-pointer hover:opacity-60">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <i class="fa-regular fa-comment"></i>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <button class="cursor-pointer hover:opacity-60">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <i class="fa-solid fa-paper-plane"></i>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button class="cursor-pointer hover:opacity-60">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <i class="fa-regular fa-bookmark"></i>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <!-- Curtidas -->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <p class="font-semibold text-sm mb-1">${post.curtidas.toLocaleString('pt-BR')} curtidas</p>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <!-- Legenda -->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <p class="text-sm leading-relaxed">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <span class="font-semibold">${post.autor}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ${post.legenda}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </p>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <!-- Tempo -->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <p class="text-xs text-gray-500 mt-2">${post.tempo}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    `;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            container.appendChild(artigo);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Função de Curtir
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function curtir(botao) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const icone = botao.querySelector('i');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (icone.classList.contains('fa-regular')) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                icone.classList.remove('fa-regular');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        icone.classList.add('fa-solid');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                icone.classList.add('text-red-500');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            icone.classList.remove('fa-solid', 'text-red-500');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    icone.classList.add('fa-regular');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Inicializar tudo
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.addEventListener('DOMContentLoaded', () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            carregarStories();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                carregarPostagens();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                